begin isolation level repeatable read read only;
set local search_path=pg_catalog,public; set local time zone 'UTC'; set local standard_conforming_strings=on;
set local jit=off; set local work_mem='4MB'; set local max_parallel_workers_per_gather=0;
set local statement_timeout='15s'; set local idle_in_transaction_session_timeout='30s'; set local lock_timeout='2s';
set local chillywood.refund_proof_inverse='{}';
set local chillywood.refund_proof_types='{}';
set local chillywood.refund_proof_catalog='{}';
set local chillywood.refund_proof_data='{}';
set local chillywood.refund_proof_history='{}';
-- stage: inverse
DO $refund_proof_stage$ DECLARE result jsonb; BEGIN select evidence into strict result from (with observed as materialized (
 select 'function:'||n.nspname||'.'||p.proname||'('||oidvectortypes(p.proargtypes)||')' key,jsonb_build_array('function',n.nspname||'.'||p.proname||'('||oidvectortypes(p.proargtypes)||')',pg_get_functiondef(p.oid),p.proowner::regrole::text,p.proacl::text,p.prokind,p.proretset,p.proleakproof,p.proparallel,p.procost,p.prorows,p.prosupport::regproc::text,obj_description(p.oid,'pg_proc')) item
 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in ('public','private','auth','supabase_migrations','extensions') and p.prokind in ('f','p')
 union all select 'relation:'||n.nspname||'.'||c.relname,jsonb_build_array('relation',n.nspname||'.'||c.relname,c.relkind,c.relowner::regrole::text,c.relacl::text,c.relrowsecurity,c.relforcerowsecurity,c.reloptions,c.relpersistence,c.relreplident,c.relispartition,pg_get_expr(c.relpartbound,c.oid),case when c.relkind in ('v','m') then pg_get_viewdef(c.oid,true) else null end,obj_description(c.oid,'pg_class'))
 from pg_class c join pg_namespace n on n.oid=c.relnamespace where (n.nspname in ('public','private','auth','supabase_migrations','extensions') or n.nspname||'.'||c.relname in ('storage.objects','realtime.messages')) and c.relkind in ('r','p','v','m','S')
 union all select 'column:'||n.nspname||'.'||c.relname||'.'||a.attname,jsonb_build_array('column',n.nspname||'.'||c.relname,a.attname,format_type(a.atttypid,a.atttypmod),a.attnotnull,a.attacl::text,a.attidentity,a.attgenerated,pg_get_expr(d.adbin,d.adrelid),col_description(c.oid,a.attnum))
 from pg_attribute a join pg_class c on c.oid=a.attrelid join pg_namespace n on n.oid=c.relnamespace left join pg_attrdef d on d.adrelid=a.attrelid and d.adnum=a.attnum where n.nspname in ('public','private','auth','supabase_migrations','extensions') and a.attnum>0 and not a.attisdropped and c.relkind in ('r','p','v','m','S')
 union all select 'constraint:'||n.nspname||'.'||c.relname||'.'||co.conname,jsonb_build_array('constraint',n.nspname||'.'||c.relname,co.conname,pg_get_constraintdef(co.oid),co.convalidated)
 from pg_constraint co join pg_class c on c.oid=co.conrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','private','auth','supabase_migrations','extensions')
 union all select 'index:'||n.nspname||'.'||idx.relname,jsonb_build_array('index',n.nspname||'.'||c.relname,idx.relname,pg_get_indexdef(i.indexrelid),i.indisvalid,i.indisready)
 from pg_index i join pg_class c on c.oid=i.indrelid join pg_class idx on idx.oid=i.indexrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','private','auth','supabase_migrations','extensions')
 union all select 'policy:'||n.nspname||'.'||c.relname||'.'||p.polname,jsonb_build_array('policy',n.nspname||'.'||c.relname,p.polname,p.polcmd,p.polpermissive,(select array_agg(r::regrole::text order by r::regrole::text collate "C") from unnest(p.polroles) r),pg_get_expr(p.polqual,p.polrelid),pg_get_expr(p.polwithcheck,p.polrelid))
 from pg_policy p join pg_class c on c.oid=p.polrelid join pg_namespace n on n.oid=c.relnamespace where (n.nspname in ('public','private','auth','supabase_migrations','extensions') or n.nspname||'.'||c.relname in ('storage.objects','realtime.messages'))
 union all select 'trigger:'||n.nspname||'.'||c.relname||'.'||case when t.tgisinternal then co.conrelid::regclass::text||'.'||co.conname::text||'.'||t.tgfoid::regproc::text else t.tgname::text end,
 jsonb_build_array('trigger',n.nspname||'.'||c.relname,case when t.tgisinternal then null else t.tgname end,t.tgisinternal,t.tgfoid::regprocedure::text,t.tgtype,t.tgenabled,t.tgdeferrable,t.tginitdeferred,co.conrelid::regclass::text,co.conname,case when t.tgisinternal then null else pg_get_triggerdef(t.oid) end)
 from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace left join pg_constraint co on co.oid=t.tgconstraint where n.nspname in ('public','private','auth','supabase_migrations','extensions')
 union all select 'sequence:'||n.nspname||'.'||c.relname,jsonb_build_array('sequence',n.nspname||'.'||c.relname,format_type(s.seqtypid,null),s.seqstart,s.seqincrement,s.seqmax,s.seqmin,s.seqcache,s.seqcycle)
 from pg_sequence s join pg_class c on c.oid=s.seqrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','private','auth','supabase_migrations','extensions')
 union all select 'schema:'||nspname,jsonb_build_array('schema',nspname,nspowner::regrole::text,nspacl::text) from pg_namespace where nspname in ('public','private','auth','supabase_migrations','extensions')
 union all select 'default_acl:'||d.defaclrole::regrole::text||'.'||coalesce(n.nspname,'')||'.'||d.defaclobjtype::text,jsonb_build_array('default_acl',d.defaclrole::regrole::text,n.nspname,d.defaclobjtype,d.defaclacl::text) from pg_default_acl d left join pg_namespace n on n.oid=d.defaclnamespace
 union all select 'role:'||rolname,jsonb_build_array('role',rolname,rolsuper,rolinherit,rolcreaterole,rolcreatedb,rolcanlogin,rolreplication,rolbypassrls,rolconnlimit,rolvaliduntil,encode(sha256(convert_to(coalesce(to_jsonb(rolconfig)::text,'null'),'UTF8')),'hex')) from pg_roles
 union all select 'membership:'||roleid::regrole::text||'.'||member::regrole::text||'.'||grantor::regrole::text,jsonb_build_array('membership',roleid::regrole::text,member::regrole::text,grantor::regrole::text,admin_option,inherit_option,set_option) from pg_auth_members
 union all select 'event_trigger:'||evtname::text,jsonb_build_array('event_trigger',evtname,evtevent,evtowner::regrole::text,evtfoid::regprocedure::text,evtenabled,evttags) from pg_event_trigger
 union all select 'role_setting:'||coalesce(d.datname,'*')||'.'||coalesce(r.rolname,'*'),jsonb_build_array('role_setting',d.datname,r.rolname,encode(sha256(convert_to(coalesce(to_jsonb(s.setconfig)::text,'null'),'UTF8')),'hex'))
 from pg_db_role_setting s left join pg_database d on d.oid=s.setdatabase left join pg_roles r on r.oid=s.setrole
),
 delta as materialized (select value->>'key' key,(value->>'beforeText')::jsonb before_item,(value->>'afterText')::jsonb after_item from jsonb_array_elements('[{"key":"constraint:public.notifications.notifications_notification_type_check","beforeText":"[\"constraint\", \"public.notifications\", \"notifications_notification_type_check\", \"CHECK (((notification_type = ANY (ARRAY[''followed_creator_live''::text, ''circle_friend_live''::text, ''event_starts_soon''::text, ''watch_party_starts_soon''::text, ''public_upload''::text, ''replay_later''::text, ''creator_went_live''::text, ''upcoming_event_reminder''::text, ''new_message''::text, ''access_granted''::text, ''content_dropped''::text, ''reply_comment''::text, ''moderation_notice''::text, ''payment_access_confirmation''::text, ''chilly_chat_call''::text, ''chilly_chat_missed_call''::text, ''paid_video_unlocked''::text, ''watch_party_ticket_ready''::text, ''live_watch_party_access_ready''::text, ''live_watch_party_seat_eligible''::text, ''live_watch_party_seat_requested''::text, ''live_watch_party_seat_approved''::text, ''live_watch_party_seat_rejected''::text, ''channel_subscription_active''::text, ''vip_access_active''::text, ''event_pass_active''::text, ''tip_sent_receipt''::text, ''paid_video_sold''::text, ''watch_party_ticket_sold''::text, ''live_watch_party_access_sold''::text, ''live_watch_party_seat_sold''::text, ''channel_subscription_started''::text, ''vip_pass_sold''::text, ''event_pass_sold''::text, ''tip_received''::text, ''creator_money_refunded''::text, ''creator_money_revoked''::text, ''event_pass_event_starts_soon''::text, ''watch_party_ticket_room_starts_soon''::text, ''payout_readiness_updated''::text, ''social_follow''::text, ''social_follow_request''::text, ''social_follow_accepted''::text, ''circle_request''::text, ''circle_accepted''::text, ''circle_added''::text, ''circle_post''::text, ''content_shared''::text, ''content_liked''::text, ''profile_post_liked''::text, ''profile_comment''::text, ''profile_reply''::text, ''video_comment''::text, ''video_reply''::text, ''chat_message''::text, ''video_view_summary''::text, ''live_view_summary''::text, ''creator_event_updated''::text, ''creator_event_canceled''::text])) OR (notification_type = ANY (ARRAY[''auction_outbid''::text, ''auction_won''::text, ''auction_creator_award''::text, ''auction_checkout_deadline''::text, ''auction_payment_deadline''::text])) OR (notification_type = ''live_room_member_joined''::text)))\", true]","afterText":"[\"constraint\", \"public.notifications\", \"notifications_notification_type_check\", \"CHECK (((notification_type = ANY (ARRAY[''followed_creator_live''::text, ''circle_friend_live''::text, ''event_starts_soon''::text, ''watch_party_starts_soon''::text, ''public_upload''::text, ''replay_later''::text, ''creator_went_live''::text, ''upcoming_event_reminder''::text, ''new_message''::text, ''access_granted''::text, ''content_dropped''::text, ''reply_comment''::text, ''moderation_notice''::text, ''payment_access_confirmation''::text, ''chilly_chat_call''::text, ''chilly_chat_missed_call''::text, ''paid_video_unlocked''::text, ''watch_party_ticket_ready''::text, ''live_watch_party_access_ready''::text, ''live_watch_party_seat_eligible''::text, ''live_watch_party_seat_requested''::text, ''live_watch_party_seat_approved''::text, ''live_watch_party_seat_rejected''::text, ''channel_subscription_active''::text, ''vip_access_active''::text, ''event_pass_active''::text, ''tip_sent_receipt''::text, ''paid_video_sold''::text, ''watch_party_ticket_sold''::text, ''live_watch_party_access_sold''::text, ''live_watch_party_seat_sold''::text, ''channel_subscription_started''::text, ''vip_pass_sold''::text, ''event_pass_sold''::text, ''tip_received''::text, ''creator_money_refunded''::text, ''creator_money_revoked''::text, ''event_pass_event_starts_soon''::text, ''watch_party_ticket_room_starts_soon''::text, ''payout_readiness_updated''::text, ''social_follow''::text, ''social_follow_request''::text, ''social_follow_accepted''::text, ''circle_request''::text, ''circle_accepted''::text, ''circle_added''::text, ''circle_post''::text, ''content_shared''::text, ''content_liked''::text, ''profile_post_liked''::text, ''profile_comment''::text, ''profile_reply''::text, ''video_comment''::text, ''video_reply''::text, ''chat_message''::text, ''video_view_summary''::text, ''live_view_summary''::text, ''creator_event_updated''::text, ''creator_event_canceled''::text])) OR (notification_type = ANY (ARRAY[''auction_outbid''::text, ''auction_won''::text, ''auction_creator_award''::text, ''auction_checkout_deadline''::text, ''auction_payment_deadline''::text])) OR (notification_type = ''live_room_member_joined''::text) OR (notification_type = ''sandbox_cashout_status_updated''::text)))\", true]"},{"key":"function:private.enqueue_sandbox_cashout_notification()","beforeText":null,"afterText":"[\"function\", \"private.enqueue_sandbox_cashout_notification()\", \"CREATE OR REPLACE FUNCTION private.enqueue_sandbox_cashout_notification()\\n RETURNS trigger\\n LANGUAGE plpgsql\\n SECURITY DEFINER\\n SET search_path TO ''''\\nAS $function$\\ndeclare state text:=private.sandbox_cashout_notification_state(new.phase);\\nbegin\\n  if state is null then return new; end if;\\n  if tg_op=''UPDATE'' and state is not distinct from private.sandbox_cashout_notification_state(old.phase)\\n    then return new; end if;\\n  -- Same transaction as the execution. If enqueue fails the RPC fails and the\\n  -- existing reconciliation retry can recover; never silently lose the notice.\\n  perform private.enqueue_notification_activity(''sandbox-cashout:''||new.id::text||'':''||state,\\n    ''sandbox_cashout_status_updated'',new.id::text,null,new.creator_id,\\n    jsonb_build_object(''state'',state,''environment'',''test''),clock_timestamp(),clock_timestamp()+interval ''7 days'');\\n  return new;\\nend $function$\\n\", \"postgres\", \"{postgres=X/postgres}\", \"f\", false, false, \"u\", 100, 0, \"-\", null]"},{"key":"function:private.resolve_account_notification_activity(notification_activity_events)","beforeText":"[\"function\", \"private.resolve_account_notification_activity(notification_activity_events)\", \"CREATE OR REPLACE FUNCTION private.resolve_account_notification_activity(p_event notification_activity_events)\\n RETURNS jsonb\\n LANGUAGE plpgsql\\n STABLE SECURITY DEFINER\\n SET search_path TO ''''\\nAS $function$\\ndeclare s private.merch_reconciliation_alert_state; recovered boolean;\\nbegin\\n if p_event.event_kind<>''owner_reconciliation_health'' then\\n  return private.resolve_account_notification_before_reconciliation(p_event); end if;\\n select * into s from private.merch_reconciliation_alert_state where singleton;\\n if not public.platform_subject_has_role_internal(p_event.recipient_user_id::text,array[''owner''])\\n  or p_event.actor_user_id is not null or p_event.source_id is distinct from s.episode::text\\n  or p_event.context->>''episode'' is distinct from s.episode::text\\n then return ''{\\\"eligible\\\":false}''::jsonb; end if;\\n recovered:=s.alerts=''[]''::jsonb;\\n return jsonb_build_object(''eligible'',true,''preference_key'',''account_activity_enabled'',\\n  ''category'',''moderation_notice'',''notification_type'',''payout_readiness_updated'',\\n  ''title'',case when recovered then ''Chi''''llywood operations: checks recovered'' else ''Chi''''llywood operations need attention'' end,\\n  ''body'',case when recovered then ''The monitored shipment and cost-refresh warnings cleared. This does not enable payments or payouts.''\\n    else ''Open Owner Money Center to review shipment verification, provider refresh and queue health. Payments and payouts are not enabled by this alert.'' end,\\n  ''target_route'',''/admin'',''target_entity_id'',s.episode::text,\\n  ''target_context'',jsonb_build_object(''section'',''money'',''alertCodes'',s.alerts,''observedAt'',s.last_checked_at),\\n  ''push_allowed'',true);\\nend $function$\\n\", \"postgres\", \"{postgres=X/postgres}\", \"f\", false, false, \"u\", 100, 0, \"-\", null]","afterText":"[\"function\", \"private.resolve_account_notification_activity(notification_activity_events)\", \"CREATE OR REPLACE FUNCTION private.resolve_account_notification_activity(p_event notification_activity_events)\\n RETURNS jsonb\\n LANGUAGE plpgsql\\n STABLE SECURITY DEFINER\\n SET search_path TO ''''\\nAS $function$\\ndeclare e private.sandbox_cashout_executions; state text;\\nbegin\\n  if p_event.event_kind<>''sandbox_cashout_status_updated'' then\\n    return private.resolve_account_notification_before_sandbox_cashout(p_event);\\n  end if;\\n  select * into e from private.sandbox_cashout_executions\\n    where id=private.seat_notification_uuid(p_event.source_id);\\n  state:=private.sandbox_cashout_notification_state(e.phase);\\n  if e.id is null or state is null or e.creator_id is distinct from p_event.recipient_user_id\\n    or p_event.actor_user_id is not null or p_event.context->>''environment'' is distinct from ''test''\\n    or p_event.context->>''state'' is distinct from state\\n    or p_event.event_key is distinct from ''sandbox-cashout:''||e.id::text||'':''||state\\n    then return ''{\\\"eligible\\\":false}''; end if;\\n  return jsonb_build_object(''eligible'',true,''category'',''creator_money_sale'',\\n    ''notification_type'',''sandbox_cashout_status_updated'',''preference_key'',''account_activity_enabled'',\\n    ''title'',case state when ''requested'' then ''Test cashout requested'' when ''processing'' then ''Test cashout processing''\\n      when ''test_paid'' then ''Test provider reported payout paid'' when ''returning'' then ''Test cashout return pending''\\n      when ''returned'' then ''Test cashout returned'' when ''canceled'' then ''Test cashout canceled''\\n      else ''Test cashout needs review'' end,\\n    ''body'',''Request ''||left(e.id::text,8)||''. ''||case state\\n      when ''test_paid'' then ''The test provider reported paid. No real bank payment occurred.''\\n      when ''returning'' then ''Return reconciliation is pending. Open your cashout status before taking another action.''\\n      when ''returned'' then ''The test return was reconciled. No real funds moved.''\\n      when ''canceled'' then ''The test request was canceled before dispatch. No real funds moved.''\\n      when ''needs_review'' then ''Open your cashout status for the next step. Do not submit a duplicate payout.''\\n      else ''Open your cashout status to review progress. This is a test, not a real bank payment.'' end,\\n    ''target_route'',''/channel-studio'',''target_entity_id'',null,\\n    ''target_context'',jsonb_build_object(''cashoutRequestId'',e.id,''cashoutState'',state,''environment'',''test'',''financialAuthority'',false));\\nend $function$\\n\", \"postgres\", \"{postgres=X/postgres}\", \"f\", false, false, \"u\", 100, 0, \"-\", null]"},{"key":"function:private.resolve_account_notification_before_sandbox_cashout(notification_activity_events)","beforeText":null,"afterText":"[\"function\", \"private.resolve_account_notification_before_sandbox_cashout(notification_activity_events)\", \"CREATE OR REPLACE FUNCTION private.resolve_account_notification_before_sandbox_cashout(p_event notification_activity_events)\\n RETURNS jsonb\\n LANGUAGE plpgsql\\n STABLE SECURITY DEFINER\\n SET search_path TO ''''\\nAS $function$\\ndeclare s private.merch_reconciliation_alert_state; recovered boolean;\\nbegin\\n if p_event.event_kind<>''owner_reconciliation_health'' then\\n  return private.resolve_account_notification_before_reconciliation(p_event); end if;\\n select * into s from private.merch_reconciliation_alert_state where singleton;\\n if not public.platform_subject_has_role_internal(p_event.recipient_user_id::text,array[''owner''])\\n  or p_event.actor_user_id is not null or p_event.source_id is distinct from s.episode::text\\n  or p_event.context->>''episode'' is distinct from s.episode::text\\n then return ''{\\\"eligible\\\":false}''::jsonb; end if;\\n recovered:=s.alerts=''[]''::jsonb;\\n return jsonb_build_object(''eligible'',true,''preference_key'',''account_activity_enabled'',\\n  ''category'',''moderation_notice'',''notification_type'',''payout_readiness_updated'',\\n  ''title'',case when recovered then ''Chi''''llywood operations: checks recovered'' else ''Chi''''llywood operations need attention'' end,\\n  ''body'',case when recovered then ''The monitored shipment and cost-refresh warnings cleared. This does not enable payments or payouts.''\\n    else ''Open Owner Money Center to review shipment verification, provider refresh and queue health. Payments and payouts are not enabled by this alert.'' end,\\n  ''target_route'',''/admin'',''target_entity_id'',s.episode::text,\\n  ''target_context'',jsonb_build_object(''section'',''money'',''alertCodes'',s.alerts,''observedAt'',s.last_checked_at),\\n  ''push_allowed'',true);\\nend $function$\\n\", \"postgres\", \"{postgres=X/postgres}\", \"f\", false, false, \"u\", 100, 0, \"-\", null]"},{"key":"function:private.sandbox_cashout_notification_state(text)","beforeText":null,"afterText":"[\"function\", \"private.sandbox_cashout_notification_state(text)\", \"CREATE OR REPLACE FUNCTION private.sandbox_cashout_notification_state(p_phase text)\\n RETURNS text\\n LANGUAGE sql\\n IMMUTABLE\\n SET search_path TO ''''\\nAS $function$\\n  select case\\n    when p_phase=''prepared'' then ''requested''\\n    when p_phase in (''funding_unknown'',''funded'',''payout_unknown'',''payout_pending'') then ''processing''\\n    when p_phase=''paid'' then ''test_paid''\\n    when p_phase in (''return_pending'',''return_confirmed'',''reversal_unknown'',''funding_return_pending'',''funding_return_unknown'') then ''returning''\\n    when p_phase=''returned'' then ''returned''\\n    when p_phase=''canceled'' then ''canceled''\\n    when p_phase=''needs_review'' then ''needs_review''\\n    else null end;\\n$function$\\n\", \"postgres\", \"{postgres=X/postgres}\", \"f\", false, false, \"u\", 100, 0, \"-\", null]"},{"key":"function:public.read_authorized_creator_video_engagement(uuid)","beforeText":null,"afterText":"[\"function\", \"public.read_authorized_creator_video_engagement(uuid)\", \"CREATE OR REPLACE FUNCTION public.read_authorized_creator_video_engagement(p_video_id uuid)\\n RETURNS TABLE(video_id uuid, like_count bigint, comment_count bigint, liked_by_viewer boolean, can_like boolean, repost_count bigint, reposted_by_viewer boolean, can_repost boolean)\\n LANGUAGE sql\\n STABLE SECURITY DEFINER ROWS 1\\n SET search_path TO ''''\\nAS $function$\\n  select v.id,coalesce(sum(c.like_count),0)::bigint,coalesce(sum(c.comment_count),0)::bigint,\\n    exists(select 1 from video_engagement_private.likes l where l.video_id=v.id and l.user_id=auth.uid()),\\n    auth.uid() is not null and public.wave1_current_caller_authority_internal(),\\n    coalesce(sum(c.repost_count),0)::bigint,\\n    exists(select 1 from video_engagement_private.reposts r where r.video_id=v.id and r.user_id=auth.uid() and r.published),\\n    auth.uid() is not null and public.wave1_current_caller_authority_internal()\\n      and exists(select 1 from public.user_profiles p where p.user_id=auth.uid()::text and p.shares_visibility=''public''\\n        and p.profile_access_visibility=''public'' and p.profile_visibility=''everyone'')\\n  from public.videos v left join video_engagement_private.counts c on c.video_id=v.id\\n  where v.id=p_video_id and v.visibility=''public'' and v.moderation_status in (''clean'',''reported'')\\n    and v.quarantined_at is null and public.media_scan_public_safe(v.scan_status)\\n    and public.can_read_creator_video_row(v.owner_id::text,v.visibility,v.moderation_status,v.scan_status,\\n      v.storage_path,v.storage_object_key,v.playback_url,auth.uid()::text)\\n  group by v.id\\n$function$\\n\", \"postgres\", \"{postgres=X/postgres,anon=X/postgres,authenticated=X/postgres}\", \"f\", true, false, \"u\", 100, 1, \"-\", null]"},{"key":"function:public.read_comment_likes_batch(text, uuid[])","beforeText":null,"afterText":"[\"function\", \"public.read_comment_likes_batch(text, uuid[])\", \"CREATE OR REPLACE FUNCTION public.read_comment_likes_batch(p_kind text, p_comment_ids uuid[])\\n RETURNS TABLE(comment_id uuid, like_count bigint, liked_by_viewer boolean, can_like boolean)\\n LANGUAGE plpgsql\\n STABLE SECURITY DEFINER\\n SET search_path TO ''''\\nAS $function$\\ndeclare target uuid;\\nbegin\\n  if p_kind not in (''profile_post_comment'',''creator_video_comment'') or p_kind is null\\n    or coalesce(cardinality(p_comment_ids),0)>50 then raise exception ''Invalid comment batch.'' using errcode=''22023''; end if;\\n  for target in select distinct x.id from unnest(coalesce(p_comment_ids,''{}''::uuid[])) x(id) where x.id is not null loop\\n    if comment_likes_private.visible(p_kind,target) then\\n      return query select target,coalesce(sum(c.likes),0)::bigint,\\n        exists(select 1 from comment_likes_private.likes l where l.kind=p_kind and l.comment_id=target and l.user_id=auth.uid()),\\n        auth.uid() is not null\\n      from comment_likes_private.counts c where c.kind=p_kind and c.comment_id=target;\\n    end if;\\n  end loop;\\nend;\\n$function$\\n\", \"postgres\", \"{postgres=X/postgres,anon=X/postgres,authenticated=X/postgres}\", \"f\", true, false, \"u\", 100, 1000, \"-\", null]"},{"key":"function:public.read_creator_video_engagement_batch(uuid[])","beforeText":null,"afterText":"[\"function\", \"public.read_creator_video_engagement_batch(uuid[])\", \"CREATE OR REPLACE FUNCTION public.read_creator_video_engagement_batch(p_video_ids uuid[])\\n RETURNS TABLE(video_id uuid, like_count bigint, comment_count bigint, liked_by_viewer boolean, can_like boolean, repost_count bigint, reposted_by_viewer boolean, can_repost boolean)\\n LANGUAGE plpgsql\\n STABLE\\n SET search_path TO ''''\\nAS $function$\\ndeclare target uuid;\\nbegin\\n  if coalesce(cardinality(p_video_ids),0)>50 then raise exception ''Too many videos.'' using errcode=''22023''; end if;\\n  for target in select distinct x.id from unnest(coalesce(p_video_ids,''{}''::uuid[])) x(id) where x.id is not null\\n  loop\\n    -- Keep source RLS as well as the aggregate helper''s explicit authority.\\n    perform 1 from public.videos v where v.id=target;\\n    if not found then continue; end if;\\n    return query select * from public.read_authorized_creator_video_engagement(target);\\n  end loop;\\nend;\\n$function$\\n\", \"postgres\", \"{postgres=X/postgres,anon=X/postgres,authenticated=X/postgres}\", \"f\", true, false, \"u\", 100, 1000, \"-\", \"At most 50 current-source-authorized public video summaries. comment_count means visible top-level discussion threads, excluding replies. 64 shards per video; no reaction identities, private messages, fabricated views or share-sheet counts.\"]"},{"key":"function:public.read_creator_video_reposts(text, timestamp with time zone, uuid, integer)","beforeText":null,"afterText":"[\"function\", \"public.read_creator_video_reposts(text, timestamp with time zone, uuid, integer)\", \"CREATE OR REPLACE FUNCTION public.read_creator_video_reposts(p_user_id text, p_before_created_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_before_video_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 24)\\n RETURNS jsonb\\n LANGUAGE plpgsql\\n STABLE SECURITY DEFINER\\n SET search_path TO ''''\\nAS $function$\\ndeclare item record; result jsonb:=''[]''; last_at timestamptz; last_id uuid; scanned integer:=0; more boolean:=false;\\nbegin\\n  if p_limit is null or p_limit<1 or p_limit>50 or (p_before_created_at is null)<>(p_before_video_id is null)\\n    or p_user_id is null or p_user_id !~* ''^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$''\\n  then raise exception ''Invalid repost page.'' using errcode=''22023''; end if;\\n  if (auth.uid() is not null and not public.wave1_current_caller_authority_internal())\\n    or public.is_account_access_restricted(p_user_id) or not public.can_view_profile_content(p_user_id)\\n    or not exists(select 1 from public.user_profiles where user_id=p_user_id and shares_visibility=''public'')\\n  then return null; end if;\\n  for item in select r.video_id,r.created_at from video_engagement_private.reposts r\\n    where r.user_id=p_user_id::uuid and r.published\\n      and (p_before_created_at is null or (r.created_at,r.video_id)<(p_before_created_at,p_before_video_id))\\n    order by r.created_at desc,r.video_id desc limit p_limit+1\\n  loop\\n    scanned:=scanned+1;\\n    if scanned>p_limit then more:=true; exit; end if;\\n    last_at:=item.created_at; last_id:=item.video_id;\\n    if exists(select 1 from public.read_authorized_creator_video_engagement(item.video_id)) then\\n      result:=result||jsonb_build_array(jsonb_build_object(''videoId'',item.video_id,''createdAt'',item.created_at));\\n    end if;\\n  end loop;\\n  return jsonb_build_object(''items'',result,''nextCursor'',case when more then jsonb_build_object(''createdAt'',last_at,''videoId'',last_id) else null end);\\nend;\\n$function$\\n\", \"postgres\", \"{postgres=X/postgres,anon=X/postgres,authenticated=X/postgres}\", \"f\", false, false, \"u\", 100, 0, \"-\", null]"},{"key":"function:public.reserve_notification_activity_push(uuid, uuid, uuid)","beforeText":"[\"function\", \"public.reserve_notification_activity_push(uuid, uuid, uuid)\", \"CREATE OR REPLACE FUNCTION public.reserve_notification_activity_push(p_event_id uuid, p_lease_token uuid, p_push_token_id uuid)\\n RETURNS jsonb\\n LANGUAGE plpgsql\\n SECURITY DEFINER\\n SET search_path TO ''''\\nAS $function$\\ndeclare e public.notification_activity_events;b private.room_start_notification_bindings;result jsonb;state text;\\nbegin\\n  select * into e from public.notification_activity_events where id=p_event_id;\\n  b:=private.current_room_start_notification_binding(e);\\n  if b.event_id is null or e.status<>''leased'' or e.lease_token is distinct from p_lease_token or e.lease_until<=now()\\n    then return public.reserve_notification_activity_push_pre_room_start(p_event_id,p_lease_token,p_push_token_id); end if;\\n  perform 1 from public.watch_party_rooms where party_id=b.party_id for share;\\n  b:=private.current_room_start_notification_binding(e);\\n  if b.event_id is null then return public.reserve_notification_activity_push_pre_room_start(p_event_id,p_lease_token,p_push_token_id); end if;\\n  state:=private.room_start_notification_delivery_state(b);\\n  if state in (''delivered'',''pending'') then return private.defer_duplicate_room_start(e,state); end if;\\n  result:=public.reserve_notification_activity_push_pre_room_start(p_event_id,p_lease_token,p_push_token_id);\\n  if result->>''eligible''=''true'' then\\n    insert into private.room_start_notification_deliveries(party_id,room_generation,recipient_user_id,winner_event_id)\\n      values(b.party_id,b.room_generation,b.recipient_user_id,e.id) on conflict do nothing;\\n  end if;\\n  return result;\\nend $function$\\n\", \"postgres\", \"{postgres=X/postgres,service_role=X/postgres}\", \"f\", false, false, \"u\", 100, 0, \"-\", null]","afterText":"[\"function\", \"public.reserve_notification_activity_push(uuid, uuid, uuid)\", \"CREATE OR REPLACE FUNCTION public.reserve_notification_activity_push(p_event_id uuid, p_lease_token uuid, p_push_token_id uuid)\\n RETURNS jsonb\\n LANGUAGE plpgsql\\n SECURITY DEFINER\\n SET search_path TO ''''\\nAS $function$\\ndeclare result jsonb;\\nbegin\\n  result:=public.reserve_notification_activity_push_before_sandbox_cashout(p_event_id,p_lease_token,p_push_token_id);\\n  if result->>''eligible''=''true'' and exists(select 1 from public.notification_activity_events\\n    where id=p_event_id and event_kind=''sandbox_cashout_status_updated'') then\\n    result:=result||jsonb_build_object(''title'',''Account update'',''body'',''Open Chi''''llywood to review your latest update.'',\\n      ''data'',jsonb_strip_nulls(jsonb_build_object(''notificationId'',result#>''{data,notificationId}'',\\n        ''route'',''/channel-studio'',''targetRoute'',''/channel-studio'')));\\n  end if;\\n  return result;\\nend $function$\\n\", \"postgres\", \"{postgres=X/postgres,service_role=X/postgres}\", \"f\", false, false, \"u\", 100, 0, \"-\", null]"},{"key":"function:public.reserve_notification_activity_push_before_sandbox_cashout(uuid, uuid, uuid)","beforeText":null,"afterText":"[\"function\", \"public.reserve_notification_activity_push_before_sandbox_cashout(uuid, uuid, uuid)\", \"CREATE OR REPLACE FUNCTION public.reserve_notification_activity_push_before_sandbox_cashout(p_event_id uuid, p_lease_token uuid, p_push_token_id uuid)\\n RETURNS jsonb\\n LANGUAGE plpgsql\\n SECURITY DEFINER\\n SET search_path TO ''''\\nAS $function$\\ndeclare e public.notification_activity_events;b private.room_start_notification_bindings;result jsonb;state text;\\nbegin\\n  select * into e from public.notification_activity_events where id=p_event_id;\\n  b:=private.current_room_start_notification_binding(e);\\n  if b.event_id is null or e.status<>''leased'' or e.lease_token is distinct from p_lease_token or e.lease_until<=now()\\n    then return public.reserve_notification_activity_push_pre_room_start(p_event_id,p_lease_token,p_push_token_id); end if;\\n  perform 1 from public.watch_party_rooms where party_id=b.party_id for share;\\n  b:=private.current_room_start_notification_binding(e);\\n  if b.event_id is null then return public.reserve_notification_activity_push_pre_room_start(p_event_id,p_lease_token,p_push_token_id); end if;\\n  state:=private.room_start_notification_delivery_state(b);\\n  if state in (''delivered'',''pending'') then return private.defer_duplicate_room_start(e,state); end if;\\n  result:=public.reserve_notification_activity_push_pre_room_start(p_event_id,p_lease_token,p_push_token_id);\\n  if result->>''eligible''=''true'' then\\n    insert into private.room_start_notification_deliveries(party_id,room_generation,recipient_user_id,winner_event_id)\\n      values(b.party_id,b.room_generation,b.recipient_user_id,e.id) on conflict do nothing;\\n  end if;\\n  return result;\\nend $function$\\n\", \"postgres\", \"{postgres=X/postgres}\", \"f\", false, false, \"u\", 100, 0, \"-\", null]"},{"key":"function:public.set_comment_like(text, uuid, boolean)","beforeText":null,"afterText":"[\"function\", \"public.set_comment_like(text, uuid, boolean)\", \"CREATE OR REPLACE FUNCTION public.set_comment_like(p_kind text, p_comment_id uuid, p_liked boolean)\\n RETURNS boolean\\n LANGUAGE plpgsql\\n SECURITY DEFINER\\n SET search_path TO ''''\\nAS $function$\\ndeclare viewer uuid:=auth.uid(); source_id uuid; parent_id uuid;\\nbegin\\n  if viewer is null then raise exception ''Current signed-in account required.'' using errcode=''42501''; end if;\\n  perform 1 from auth.users where id=viewer for share;\\n  if not public.wave1_current_caller_authority_internal() or public.is_account_access_restricted(viewer::text)\\n    then raise exception ''Current signed-in account required.'' using errcode=''42501''; end if;\\n  if p_kind is null or p_kind not in (''profile_post_comment'',''creator_video_comment'') or p_comment_id is null or p_liked is null\\n    then raise exception ''Comment and desired state required.'' using errcode=''22023''; end if;\\n  insert into comment_likes_private.limits(user_id,started_at,attempts) values(viewer,clock_timestamp(),1)\\n  on conflict(user_id) do update set\\n    started_at=case when comment_likes_private.limits.started_at<=clock_timestamp()-interval ''1 minute'' then clock_timestamp() else comment_likes_private.limits.started_at end,\\n    attempts=case when comment_likes_private.limits.started_at<=clock_timestamp()-interval ''1 minute'' then 1 else comment_likes_private.limits.attempts+1 end\\n  where comment_likes_private.limits.started_at<=clock_timestamp()-interval ''1 minute'' or comment_likes_private.limits.attempts<120;\\n  if not found then raise exception ''rate_limited'' using errcode=''P0001''; end if;\\n  if not p_liked then\\n    -- Withdrawal remains possible after source privacy changes, without exposing existence.\\n    delete from comment_likes_private.likes where kind=p_kind and comment_id=p_comment_id and user_id=viewer;\\n    return false;\\n  end if;\\n  -- Lock source before child to agree with cascading deletes. Recheck all current\\n  -- predicates after locks; no client IDs/timestamps/counter deltas grant access.\\n  if p_kind=''profile_post_comment'' then\\n    select c.post_id,c.parent_comment_id into source_id,parent_id from public.profile_post_comments c where c.id=p_comment_id;\\n    perform 1 from public.profile_posts where id=source_id for share;\\n    if parent_id is not null then perform 1 from public.profile_post_comments where id=parent_id for share; end if;\\n    perform 1 from public.profile_post_comments where id=p_comment_id and post_id=source_id for share;\\n  else\\n    select c.video_id,c.parent_comment_id into source_id,parent_id from public.creator_video_comments c where c.id=p_comment_id;\\n    perform 1 from public.videos where id=source_id for share;\\n    if parent_id is not null then perform 1 from public.creator_video_comments where id=parent_id for share; end if;\\n    perform 1 from public.creator_video_comments where id=p_comment_id and video_id=source_id for share;\\n  end if;\\n  if not found or not comment_likes_private.visible(p_kind,p_comment_id) then raise exception ''Comment unavailable.'' using errcode=''42501''; end if;\\n  insert into comment_likes_private.likes(kind,comment_id,user_id) values(p_kind,p_comment_id,viewer) on conflict do nothing;\\n  return true;\\nend;\\n$function$\\n\", \"postgres\", \"{postgres=X/postgres,authenticated=X/postgres}\", \"f\", false, false, \"u\", 100, 0, \"-\", null]"},{"key":"function:public.set_creator_video_like(uuid, boolean)","beforeText":null,"afterText":"[\"function\", \"public.set_creator_video_like(uuid, boolean)\", \"CREATE OR REPLACE FUNCTION public.set_creator_video_like(p_video_id uuid, p_liked boolean)\\n RETURNS boolean\\n LANGUAGE plpgsql\\n SECURITY DEFINER\\n SET search_path TO ''''\\nAS $function$\\ndeclare viewer uuid:=auth.uid(); v public.videos%rowtype;\\nbegin\\n  if viewer is null or not public.wave1_current_caller_authority_internal()\\n    or public.is_account_access_restricted(viewer::text)\\n  then raise exception ''Current signed-in account required.'' using errcode=''42501''; end if;\\n  if p_video_id is null or p_liked is null then raise exception ''Video and desired state required.'' using errcode=''22023''; end if;\\n  -- One row per account serializes mutations and bounds concurrent spam. Never\\n  -- trust client timestamps or a client-supplied counter delta.\\n  insert into video_engagement_private.write_limits(user_id,started_at,attempts) values(viewer,clock_timestamp(),1)\\n  on conflict(user_id) do update set\\n    started_at=case when video_engagement_private.write_limits.started_at<=clock_timestamp()-interval ''1 minute''\\n      then clock_timestamp() else video_engagement_private.write_limits.started_at end,\\n    attempts=case when video_engagement_private.write_limits.started_at<=clock_timestamp()-interval ''1 minute''\\n      then 1 else video_engagement_private.write_limits.attempts+1 end\\n  where video_engagement_private.write_limits.started_at<=clock_timestamp()-interval ''1 minute''\\n    or video_engagement_private.write_limits.attempts<60;\\n  if not found then raise exception ''rate_limited'' using errcode=''P0001''; end if;\\n  if not p_liked then\\n    -- Withdrawal does not reveal whether a now-private/removed video exists.\\n    delete from video_engagement_private.likes where video_id=p_video_id and user_id=viewer;\\n    return false;\\n  end if;\\n  select * into v from public.videos where id=p_video_id for share;\\n  if not found or v.visibility<>''public'' or v.moderation_status not in (''clean'',''reported'')\\n    or v.quarantined_at is not null or not public.media_scan_public_safe(v.scan_status)\\n    or not public.can_read_creator_video_row(v.owner_id::text,v.visibility,v.moderation_status,v.scan_status,\\n      v.storage_path,v.storage_object_key,v.playback_url,viewer::text)\\n  then raise exception ''Video unavailable.'' using errcode=''42501''; end if;\\n  insert into video_engagement_private.likes(video_id,user_id) values(p_video_id,viewer) on conflict do nothing;\\n  return true;\\nend;\\n$function$\\n\", \"postgres\", \"{postgres=X/postgres,authenticated=X/postgres}\", \"f\", false, false, \"u\", 100, 0, \"-\", null]"},{"key":"function:public.set_creator_video_repost(uuid, boolean)","beforeText":null,"afterText":"[\"function\", \"public.set_creator_video_repost(uuid, boolean)\", \"CREATE OR REPLACE FUNCTION public.set_creator_video_repost(p_video_id uuid, p_reposted boolean)\\n RETURNS boolean\\n LANGUAGE plpgsql\\n SECURITY DEFINER\\n SET search_path TO ''''\\nAS $function$\\ndeclare viewer uuid:=auth.uid(); v public.videos%rowtype; profile public.user_profiles%rowtype;\\nbegin\\n  if viewer is null or not public.wave1_current_caller_authority_internal() or public.is_account_access_restricted(viewer::text)\\n  then raise exception ''Current signed-in account required.'' using errcode=''42501''; end if;\\n  if p_video_id is null or p_reposted is null then raise exception ''Video and desired state required.'' using errcode=''22023''; end if;\\n  -- Serializes with ban/account-deletion flows, then profile privacy changes,\\n  -- then source withdrawal. The record is never published under stale privacy.\\n  perform 1 from auth.users where id=viewer for share;\\n  select * into profile from public.user_profiles where user_id=viewer::text for share;\\n  if public.is_account_access_restricted(viewer::text) then raise exception ''Account unavailable.'' using errcode=''42501''; end if;\\n  if not p_reposted then\\n    update video_engagement_private.reposts set published=false where video_id=p_video_id and user_id=viewer and published;\\n    return false;\\n  end if;\\n  if profile.user_id is null or profile.shares_visibility<>''public'' or profile.profile_access_visibility<>''public'' or profile.profile_visibility<>''everyone''\\n  then raise exception ''Public profile and shares required to repost.'' using errcode=''42501''; end if;\\n  -- Shared abuse budget; accounts cannot evade it by alternating like/repost.\\n  insert into video_engagement_private.write_limits(user_id,started_at,attempts) values(viewer,clock_timestamp(),1)\\n  on conflict(user_id) do update set\\n    started_at=case when video_engagement_private.write_limits.started_at<=clock_timestamp()-interval ''1 minute''\\n      then clock_timestamp() else video_engagement_private.write_limits.started_at end,\\n    attempts=case when video_engagement_private.write_limits.started_at<=clock_timestamp()-interval ''1 minute''\\n      then 1 else video_engagement_private.write_limits.attempts+1 end\\n  where video_engagement_private.write_limits.started_at<=clock_timestamp()-interval ''1 minute'' or video_engagement_private.write_limits.attempts<60;\\n  if not found then raise exception ''rate_limited''; end if;\\n  select * into v from public.videos where id=p_video_id for share;\\n  if not found or v.visibility<>''public'' or v.moderation_status not in (''clean'',''reported'') or v.quarantined_at is not null\\n    or not public.media_scan_public_safe(v.scan_status)\\n    or not public.can_read_creator_video_row(v.owner_id::text,v.visibility,v.moderation_status,v.scan_status,\\n      v.storage_path,v.storage_object_key,v.playback_url,viewer::text)\\n  then raise exception ''Video unavailable.'' using errcode=''42501''; end if;\\n  insert into video_engagement_private.reposts(video_id,user_id) values(p_video_id,viewer)\\n    on conflict(video_id,user_id) do update set published=true where not video_engagement_private.reposts.published;\\n  return true;\\nend;\\n$function$\\n\", \"postgres\", \"{postgres=X/postgres,authenticated=X/postgres}\", \"f\", false, false, \"u\", 100, 0, \"-\", null]"},{"key":"trigger:auth.users.comment_likes_private.likes.likes_user_id_fkey.\"RI_FKey_cascade_del\"","beforeText":null,"afterText":"[\"trigger\", \"auth.users\", null, true, \"\\\"RI_FKey_cascade_del\\\"()\", 9, \"O\", false, false, \"comment_likes_private.likes\", \"likes_user_id_fkey\", null]"},{"key":"trigger:auth.users.comment_likes_private.likes.likes_user_id_fkey.\"RI_FKey_noaction_upd\"","beforeText":null,"afterText":"[\"trigger\", \"auth.users\", null, true, \"\\\"RI_FKey_noaction_upd\\\"()\", 17, \"O\", false, false, \"comment_likes_private.likes\", \"likes_user_id_fkey\", null]"},{"key":"trigger:auth.users.comment_likes_private.limits.limits_user_id_fkey.\"RI_FKey_cascade_del\"","beforeText":null,"afterText":"[\"trigger\", \"auth.users\", null, true, \"\\\"RI_FKey_cascade_del\\\"()\", 9, \"O\", false, false, \"comment_likes_private.limits\", \"limits_user_id_fkey\", null]"},{"key":"trigger:auth.users.comment_likes_private.limits.limits_user_id_fkey.\"RI_FKey_noaction_upd\"","beforeText":null,"afterText":"[\"trigger\", \"auth.users\", null, true, \"\\\"RI_FKey_noaction_upd\\\"()\", 17, \"O\", false, false, \"comment_likes_private.limits\", \"limits_user_id_fkey\", null]"},{"key":"trigger:auth.users.creator_video_reposts_account_ban","beforeText":null,"afterText":"[\"trigger\", \"auth.users\", \"creator_video_reposts_account_ban\", false, \"video_engagement_private.account_ban_changed()\", 17, \"O\", false, false, null, null, \"CREATE TRIGGER creator_video_reposts_account_ban AFTER UPDATE OF banned_until ON auth.users FOR EACH ROW EXECUTE FUNCTION video_engagement_private.account_ban_changed()\"]"},{"key":"trigger:auth.users.video_engagement_private.likes.likes_user_id_fkey.\"RI_FKey_cascade_del\"","beforeText":null,"afterText":"[\"trigger\", \"auth.users\", null, true, \"\\\"RI_FKey_cascade_del\\\"()\", 9, \"O\", false, false, \"video_engagement_private.likes\",